'use strict';
const $=(s,r=document)=>r.querySelector(s);
const apps={about:{name:'About Me',icon:'✳',width:500,height:470},portfolio:{name:'FrameTheory',icon:'▰',width:620,height:560},music:{name:'Music Player',icon:'♫',width:350,height:575},terminal:{name:'Terminal',icon:'>_',width:570,height:390},settings:{name:'Settings',icon:'⚙',width:470,height:540}};
const defaults={theme:'glass',wall:'aero',sound:false,motion:matchMedia('(prefers-reduced-motion: reduce)').matches};
let prefs={...defaults};try{const saved=JSON.parse(localStorage.getItem('fizzyos.preferences')||'{}');prefs={theme:['glass','dark'].includes(saved.theme)?saved.theme:defaults.theme,wall:['aero','dusk','midnight'].includes(saved.wall)?saved.wall:defaults.wall,sound:typeof saved.sound==='boolean'?saved.sound:false,motion:typeof saved.motion==='boolean'?saved.motion:defaults.motion}}catch{}
let z=20,toastTimer,started=false;const windows=new Map();
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function applyPrefs(save=false){document.body.dataset.theme=prefs.theme;document.body.dataset.wall=prefs.wall;document.body.dataset.motion=prefs.motion?'reduced':'full';$('#sound-toggle').textContent=prefs.sound?'♪':'♩';$('#sound-toggle').setAttribute('aria-pressed',prefs.sound);if(save)try{localStorage.setItem('fizzyos.preferences',JSON.stringify(prefs))}catch{notify('Storage unavailable. Preferences apply for this visit.')}}applyPrefs();
function icon(id){return `<span class="icon ${id}">${apps[id].icon}</span>`}
for(const id of Object.keys(apps)){const a=apps[id];const b=document.createElement('button');b.className='shortcut';b.innerHTML=icon(id)+a.name;b.onclick=()=>openApp(id);$('#shortcuts').append(b);const d=document.createElement('button');d.className='dock-item';d.dataset.app=id;d.setAttribute('aria-label',a.name);d.innerHTML=icon(id)+'<span class="dot"></span>';d.onclick=()=>openApp(id);$('#dock').append(d)}
function updateClock(){$('#clock').textContent=new Date().toLocaleString(undefined,{weekday:'short',hour:'2-digit',minute:'2-digit'});$('#clock').dateTime=new Date().toISOString()}updateClock();setInterval(updateClock,1000);
let audioContext;
function getAudio(){return audioContext||(audioContext=new (window.AudioContext||window.webkitAudioContext)())}
async function chime(){try{const c=getAudio();await c.resume();[523.25,659.25,783.99].forEach((f,i)=>{const o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(0,c.currentTime);g.gain.linearRampToValueAtTime(.045,c.currentTime+.03+i*.12);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+1+i*.12);o.connect(g);g.connect(c.destination);o.start(c.currentTime+i*.12);o.stop(c.currentTime+1.2+i*.12)})}catch{notify('Audio isn’t available in this browser.')}}
$('#boot-sound').checked=prefs.sound;$('#enter').onclick=()=>{if(started)return;started=true;prefs.sound=$('#boot-sound').checked;applyPrefs(true);if(prefs.sound)chime();$('#boot').classList.add('done');$('#boot').setAttribute('aria-hidden','true');openApp('about').focus();};
$('#brand').onclick=()=>openApp('about');document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openApp(b.dataset.open));$('#show-desktop').onclick=()=>{const visible=[...windows.values()].some(w=>!w.hidden);for(const w of windows.values())w.hidden=visible;$('#active-app').textContent='Desktop'};$('#sound-toggle').onclick=()=>{prefs.sound=!prefs.sound;applyPrefs(true);if(prefs.sound)chime();notify('Interface sounds '+(prefs.sound?'on':'off'));if(windows.has('settings'))renderSettings(windows.get('settings'))};
function focusWindow(w){w.style.zIndex=++z;windows.forEach(x=>x.classList.toggle('focused',x===w));$('#active-app').textContent=apps[w.dataset.app].name}
function closeApp(id){const w=windows.get(id);if(!w)return;w.remove();windows.delete(id);$(`[data-app="${id}"].dock-item`).classList.remove('running');$('#active-app').textContent='Desktop';$(`[data-app="${id}"].dock-item`).focus()}
function openApp(id){if(!apps[id])return;let w=windows.get(id);if(w){w.hidden=false;focusWindow(w);w.focus();return w}const a=apps[id];w=document.createElement('section');w.className='window';w.dataset.app=id;w.setAttribute('role','dialog');w.setAttribute('aria-label',a.name);w.tabIndex=-1;const area=$('#desktop'),count=windows.size;const width=Math.min(a.width,area.clientWidth-24),height=Math.min(a.height,area.clientHeight-115);Object.assign(w.style,{width:width+'px',height:height+'px',left:Math.max(12,Math.min(area.clientWidth-width-18,area.clientWidth*.39+count*24))+'px',top:Math.max(12,Math.min(area.clientHeight-height-110,area.clientHeight*.12+count*22))+'px'});w.innerHTML=`<div class="titlebar"><div class="traffic"><button aria-label="Close ${a.name}" title="Close">×</button><button aria-label="Minimize ${a.name}" title="Minimize">−</button><button aria-label="Maximize ${a.name}" title="Maximize">+</button></div><span class="window-title">${a.name}</span><span class="window-version">FizzyOS / 0.1</span></div><div class="window-body"></div>`;$('#windows').append(w);windows.set(id,w);$(`[data-app="${id}"].dock-item`).classList.add('running');const controls=w.querySelectorAll('.traffic button');controls[0].onclick=()=>closeApp(id);controls[1].onclick=()=>{w.hidden=true;$('#active-app').textContent='Desktop'};controls[2].onclick=()=>w.classList.toggle('maximized');w.addEventListener('pointerdown',()=>focusWindow(w));const bar=$('.titlebar',w);bar.ondblclick=e=>{if(!e.target.closest('button'))w.classList.toggle('maximized')};bar.onpointerdown=e=>{if(e.target.closest('button')||w.classList.contains('maximized')||innerWidth<=700)return;const ox=e.clientX-w.offsetLeft,oy=e.clientY-w.offsetTop;bar.setPointerCapture(e.pointerId);bar.onpointermove=ev=>{w.style.left=Math.max(0,Math.min(area.clientWidth-w.offsetWidth,ev.clientX-ox))+'px';w.style.top=Math.max(0,Math.min(area.clientHeight-150,ev.clientY-oy))+'px'};bar.onpointerup=()=>{bar.onpointermove=null};bar.onpointercancel=()=>{bar.onpointermove=null}};({about:renderAbout,portfolio:renderPortfolio,music:renderMusic,terminal:renderTerminal,settings:renderSettings}[id])(w);focusWindow(w);return w}
window.addEventListener('resize',()=>windows.forEach(w=>{if(innerWidth<=700)return;w.style.width=Math.min(parseFloat(w.style.width),innerWidth-24)+'px';w.style.height=Math.min(parseFloat(w.style.height),innerHeight-155)+'px';w.style.left=Math.max(0,Math.min(w.offsetLeft,innerWidth-w.offsetWidth-12))+'px';w.style.top=Math.max(0,Math.min(w.offsetTop,innerHeight-190))+'px'}));
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const w=[...windows.values()].filter(w=>!w.hidden).sort((a,b)=>Number(b.style.zIndex)-Number(a.style.zIndex))[0];if(w)closeApp(w.dataset.app)}});
function renderAbout(w){$('.window-body',w).innerHTML=`<div class="app-pad"><span class="kicker">HELLO, WORLD. WELCOME TO MY CORNER.</span><div class="about-heading"><h2>Hey, I’m Fizzy<span style="color:var(--accent)">.</span></h2><div class="avatar">✳</div></div><p class="lead">A space for things I make,<br>sounds I like, and ideas in progress.</p><p class="muted">Welcome to my little experiment on the internet. Part creative playground, part personal desktop. Take a look around—there’s a little something behind every icon.</p><div class="tags"><span class="tag">↗ Creative curiosity</span><span class="tag">◌ Moving pictures</span><span class="tag">♫ Sound experiments</span></div><button class="primary" id="explore">Explore FrameTheory ↗</button> <button class="secondary" id="about-music">Put something on ♫</button><div class="about-bottom"><span>PERSONAL DESKTOP / V0.1</span><span>Bio placeholder · make it yours</span></div></div>`;$('#explore',w).onclick=()=>openApp('portfolio');$('#about-music',w).onclick=()=>openApp('music')}
const projects=[{name:'Between the frames',kind:'Film',desc:'A home for your next short film. Add a synopsis, your role, and the finished piece.',number:'01'},{name:'Everyday, differently',kind:'Photography',desc:'A collection for moments worth noticing. Replace this artwork with your own photographs.',number:'02'},{name:'After hours',kind:'Motion',desc:'An open canvas for motion studies, title sequences, and visual experiments.',number:'03'},{name:'Somewhere, someday',kind:'Film',desc:'Space for a travel film or a story still taking shape. Add your footage when you are ready.',number:'04'}];
function renderPortfolio(w,filter='All'){const body=$('.window-body',w);body.innerHTML=`<div class="app-pad"><div class="portfolio-top"><div><span class="kicker">THE CREATIVE SIDE OF THINGS</span><h2>FrameTheory<span style="color:var(--accent)">↗</span></h2></div><span class="tag">Sample library</span></div><p class="muted">A collection of stories, frames, and experiments.<br>Concept placeholders below—not completed client work.</p><div class="filters">${['All','Film','Photography','Motion'].map(x=>`<button class="filter ${filter===x?'selected':''}" data-filter="${x}">${x}</button>`).join('')}</div><div class="project-grid">${projects.map((p,i)=>filter==='All'||p.kind===filter?`<button class="project" data-project="${i}"><div class="project-art">${p.number} /</div><div class="project-info"><strong>${p.name}</strong><small>${p.kind.toUpperCase()} · PLACEHOLDER ↗</small></div></button>`:'').join('')}</div></div>`;body.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>renderPortfolio(w,b.dataset.filter));body.querySelectorAll('[data-project]').forEach(b=>b.onclick=()=>{const p=projects[Number(b.dataset.project)];body.innerHTML=`<div class="app-pad"><button class="secondary" id="back">← Library</button><div class="detail-art">${p.number} /</div><span class="kicker">${p.kind.toUpperCase()} · CONCEPT PLACEHOLDER</span><h2>${p.name}</h2><p class="muted">${p.desc}</p><p class="muted">Your story belongs here. This sample is ready to be replaced with your own images, films, and project notes.</p></div>`;$('#back',w).onclick=()=>renderPortfolio(w,filter)})}
const tracks=[{name:'Soft Focus',artist:'FizzyOS · synthesized demo',length:72,chord:[130.81,164.81,196,261.63]},{name:'Desktop Daydream',artist:'FizzyOS · synthesized demo',length:64,chord:[146.83,174.61,220,293.66]},{name:'Blue Hour',artist:'FizzyOS · synthesized demo',length:80,chord:[110,130.81,164.81,220]}];let trackIndex=0,playing=false,position=0,volume=.35,lastTick=performance.now(),voices=[],master,localAudio=null,localUrl=null;
function stopSound(){voices.forEach(o=>{try{o.stop()}catch{}});voices=[];if(master){master.disconnect();master=null}if(localAudio)localAudio.pause()}
async function playSound(){try{if(tracks[trackIndex].local){localAudio.currentTime=position;localAudio.volume=volume;await localAudio.play()}else{const c=getAudio();await c.resume();master=c.createGain();master.gain.value=volume*.07;master.connect(c.destination);tracks[trackIndex].chord.forEach((f,i)=>{const o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.value=f;g.gain.value=i===0?.9:.35;o.connect(g);g.connect(master);o.start();voices.push(o)})}playing=true;lastTick=performance.now();updatePlayer()}catch{playing=false;notify('Could not play this audio file. Try MP3, WAV, or M4A.');updatePlayer()}}
function togglePlay(){if(playing){playing=false;stopSound();updatePlayer()}else playSound()}
function selectTrack(i){const resume=playing;stopSound();playing=false;trackIndex=(i+tracks.length)%tracks.length;position=0;if(resume)playSound();if(windows.has('music'))renderMusic(windows.get('music'))}
function timeFormat(n){return `${Math.floor(n/60)}:${String(Math.floor(n%60)).padStart(2,'0')}`}
function renderMusic(w){const t=tracks[trackIndex];$('.window-body',w).innerHTML=`<div class="player"><div class="album"><span>✳</span></div><h2 id="track-title"></h2><p id="track-artist"></p><input class="progress" id="progress" aria-label="Track position" type="range" min="0" max="${t.length}" value="${position}" step=".1"><div class="times"><span id="elapsed">0:00</span><span>${timeFormat(t.length)}</span></div><div class="player-controls"><button id="previous" aria-label="Previous track">◀◀</button><button id="play" class="play" aria-label="Play">▶</button><button id="next" aria-label="Next track">▶▶</button></div><label class="volume-row">Volume <input id="volume" aria-label="Volume" type="range" min="0" max="1" step=".01" value="${volume}"></label></div><div class="tracklist" id="tracklist"></div><label class="local-file">＋ Open your own audio file<input id="audio-file" type="file" accept="audio/*"></label><p class="muted" style="text-align:center;font-size:9px;margin:0 12px 15px">Local audio stays on your device. Demo tracks are ambient synth chords.</p>`;$('#track-title',w).textContent=t.name;$('#track-artist',w).textContent=t.artist;tracks.forEach((track,i)=>{const b=document.createElement('button');b.className='track'+(i===trackIndex?' active':'');const name=document.createElement('span');name.textContent=`${String(i+1).padStart(2,'0')}   ${track.name}`;const length=document.createElement('span');length.textContent=timeFormat(track.length);b.append(name,length);b.onclick=()=>selectTrack(i);$('#tracklist',w).append(b)});$('#play',w).onclick=togglePlay;$('#previous',w).onclick=()=>selectTrack(trackIndex-1);$('#next',w).onclick=()=>selectTrack(trackIndex+1);$('#progress',w).oninput=e=>{position=Number(e.target.value);if(t.local&&localAudio)localAudio.currentTime=position;updatePlayer()};$('#volume',w).oninput=e=>{volume=Number(e.target.value);if(master)master.gain.value=volume*.07;if(localAudio)localAudio.volume=volume};$('#audio-file',w).onchange=e=>{const file=e.target.files[0];if(!file)return;stopSound();playing=false;if(localUrl)URL.revokeObjectURL(localUrl);localUrl=URL.createObjectURL(file);localAudio=new Audio(localUrl);localAudio.onloadedmetadata=()=>{if(!Number.isFinite(localAudio.duration)||localAudio.duration<=0){notify('This audio file could not be read.');return}tracks.splice(3);tracks.push({name:file.name,artist:'Your local audio · only on this device',length:localAudio.duration,local:true});trackIndex=3;position=0;renderMusic(w);notify('Local track ready. Press play.');};localAudio.onerror=()=>notify('Audio format not supported. Try MP3 or WAV.');};updatePlayer()}
function updatePlayer(){const w=windows.get('music');if(!w)return;const play=$('#play',w);if(!play)return;play.textContent=playing?'Ⅱ':'▶';play.setAttribute('aria-label',playing?'Pause':'Play');$('#elapsed',w).textContent=timeFormat(position);$('#progress',w).value=position}
setInterval(()=>{const now=performance.now();if(playing){position=tracks[trackIndex].local?localAudio.currentTime:position+(now-lastTick)/1000;if(position>=tracks[trackIndex].length-.1){selectTrack(trackIndex+1)}updatePlayer()}lastTick=now},200);
function renderTerminal(w){$('.window-body',w).innerHTML=`<div class="terminal-body"><div class="terminal-banner">✳ FizzyOS Terminal [Version 0.1]\nA tiny terminal with a big imagination.\nSimulated commands only. No shell or file access.\nType “help” to get your bearings.\n</div><div class="terminal-output" role="log" aria-live="polite"></div><form class="terminal-form"><label for="command">fizzy ~ %</label><input id="command" autocomplete="off" spellcheck="false" aria-label="Terminal command"></form></div>`;const input=$('input',w),output=$('.terminal-output',w),history=[];let cursor=0;function print(s){output.textContent+=s+'\n';$('.terminal-body',w).scrollTop=100000}$('.terminal-form',w).onsubmit=e=>{e.preventDefault();const raw=input.value.trim();if(!raw)return;history.push(raw);cursor=history.length;input.value='';print('fizzy ~ % '+raw);const cmd=raw.toLowerCase();if(cmd==='clear'){output.textContent='';return}const responses={help:'Commands: help, about, projects, music, settings, neofetch, date, ls, whoami, echo <text>, clear\nSecrets: try “sudo hire fizzy”, “coffee”, or “matrix”.',neofetch:'    ✳    FizzyOS 0.1\n   /|\\   Kernel: imagination.js\n  / | \\  Shell: safe & simulated\n         Mood: cautiously caffeinated\n         Theme: '+prefs.theme+' / '+prefs.wall,whoami:'fizzy’s guest · welcome to the little universe.',ls:'About Me.app   FrameTheory.app   Music.app\nTerminal.app   Settings.app   curiosity.txt',date:new Date().toLocaleString(),'sudo hire fizzy':'Excellent taste. Add your real contact details to About Me to make this command useful.','coffee':'☕ Brewing… creativity restored. No actual caffeine was harmed.',matrix:'01000110 01001001 01011010 01011010 01011001\nYou took the teal pill. Welcome back to the desktop.',pwd:'/home/fizzy/imagination'};if(cmd in responses)print(responses[cmd]);else if(['about','projects','music','settings'].includes(cmd)){openApp(cmd==='projects'?'portfolio':cmd);print('Opening '+cmd+'…')}else if(cmd.startsWith('echo '))print(raw.slice(5));else if(cmd==='cat curiosity.txt')print('The best way to find out is to make something.');else print('Command not found. Type “help” for the small, safe command list.')};input.onkeydown=e=>{if(e.key==='ArrowUp'){e.preventDefault();cursor=Math.max(0,cursor-1);input.value=history[cursor]||''}if(e.key==='ArrowDown'){e.preventDefault();cursor=Math.min(history.length,cursor+1);input.value=history[cursor]||''}};setTimeout(()=>input.focus(),100)}
function renderSettings(w){$('.window-body',w).innerHTML=`<div class="app-pad"><span class="kicker">MAKE YOURSELF AT HOME</span><h2 style="font-size:27px;margin:10px 0">Your desktop, your mood.</h2><p class="muted">Preferences are saved in this browser.</p><div class="settings-section"><h3>Appearance</h3><div class="theme-options">${[['glass','☀ Glass'],['dark','☾ After dark']].map(([v,l])=>`<button class="choice ${prefs.theme===v?'selected':''}" data-theme-choice="${v}" aria-pressed="${prefs.theme===v}">${l}</button>`).join('')}</div></div><div class="settings-section"><h3>Wallpaper</h3><div class="wall-options">${[['aero','Aero bloom'],['dusk','Apricot dusk'],['midnight','Midnight']].map(([v,l])=>`<button class="choice ${prefs.wall===v?'selected':''}" data-wall-choice="${v}" aria-pressed="${prefs.wall===v}"><div class="swatch ${v}"></div>${l}</button>`).join('')}</div></div><div class="settings-section"><label class="setting-row">Interface sounds<input id="settings-sound" type="checkbox" ${prefs.sound?'checked':''}></label><label class="setting-row">Reduce motion<input id="settings-motion" type="checkbox" ${prefs.motion?'checked':''}></label></div><div class="setting-row"><span class="muted">FizzyOS 0.1 · Made for the web</span><button class="secondary" id="reset">Reset preferences</button></div></div>`;w.querySelectorAll('[data-theme-choice]').forEach(b=>b.onclick=()=>{prefs.theme=b.dataset.themeChoice;applyPrefs(true);renderSettings(w)});w.querySelectorAll('[data-wall-choice]').forEach(b=>b.onclick=()=>{prefs.wall=b.dataset.wallChoice;applyPrefs(true);renderSettings(w)});$('#settings-sound',w).onchange=e=>{prefs.sound=e.target.checked;applyPrefs(true);if(prefs.sound)chime()};$('#settings-motion',w).onchange=e=>{prefs.motion=e.target.checked;applyPrefs(true)};$('#reset',w).onclick=()=>{prefs={...defaults};applyPrefs(true);renderSettings(w);notify('Back to the original atmosphere.')};}
